import time


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.75

    # Start from given solution, or a decent smooth bump.
    if start is not None:
        h = np.asarray(start, dtype=float).copy()
    else:
        N = 2000
        x = (np.arange(N) + 0.5) / N * 2 - 1
        h = np.maximum(0.0, 1.0 - x * x) ** 0.5

    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(50)

    best = h.copy()
    bestC = _C(best)

    # Coordinate-wise multiplicative refinement of the step heights.
    # C is scale invariant, so we tweak individual heights and keep improvements.
    N = len(h)
    step = 0.05
    rng = np.random.default_rng(12345)

    while time.process_time() < deadline:
        improved = False
        idx = rng.permutation(N)
        for i in idx:
            if time.process_time() >= deadline:
                break
            old = h[i]
            for factor in (1.0 + step, 1.0 / (1.0 + step)):
