def evalC(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    c = np.convolve(h, h)
    return 2.0 * len(h) * c.max() / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds - 1.5  # margin

    # Initialize
    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.ndim != 1 or len(h) == 0:
            h = np.ones(50)
    else:
        h = np.ones(50)

    N = len(h)
    best = h.copy()
    bestC = evalC(best)

    rng = np.random.default_rng(12345)

    # Local coordinate-descent / random perturbation search on heights.
    # Work in log-space to keep positivity, scale-invariant.
    def metric(x):
        hh = np.exp(x - x.max())
        return evalC(hh)

    x = np.log(np.maximum(h, 1e-12))
    curC = bestC

    step = 0.5
    while time.process_time() - t0 < budget:
        improved = False
        # try coordinate updates on random subset
        idx = rng.integers(0, N, size=min(N, 200))
        for i in idx:
            if time.process_time() - t0 >= budget:
                break
            old = x[i]
            for delta in (step, -step):
                x[i] = old + delta
                c = metric(x)
                if c < curC - 1e-12:
                    curC = c
                    improved = True
                    break
                else:
                    x[i] = old
        if not improved:
            step *= 0.7
            if step < 1e-4:
                step = 0.5

        if curC < bestC - 1e-12:
            bestC = curC
            best = np.exp(x - x.max())
            best = best / best.max()

    return best

