        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            c = _C(s)
            if c < best_C:
                best_C = c
                best_h = s.copy()

    # restarts
    rng = np.random.RandomState(12345)
    restart = 0
    while True:
        elapsed = time.process_time() - t0
        # reserve margin
        if elapsed > budget_seconds * 0.85:
            break
        if restart == 0:
            x0 = np.zeros(N)
        else:
            x0 = rng.randn(N) * 0.1

        try:
