                _objective, x0, args=(N, p),
                method='L-BFGS-B',
                options={'maxiter': 500, 'ftol': 1e-12, 'gtol': 1e-10}
            )
            x = res.x
            h = np.exp(x)
            h = h / h.sum()
            c = _C(h)
            if c < best_C:
                best_C = c
                best_h = h.copy()
        except Exception:
            pass

        restart += 1
        if restart > 50:
            break

    if best_h is None:
        best_h = np.ones(N)

    # ensure non-negative, finite, not all zero
    best_h = np.asarray(best_h, dtype=float)
    best_h = np.where(np.isfinite(best_h) & (best_h >= 0), best_h, 0.0)
    if best_h.sum() <= 0:
