    Ns = [80, 160, 320, 640, 1280]
    rng = np.random.RandomState(9876)

    # Build initial seed shapes: cosine bumps + upsampled start
    def cosine_seed(N, alpha):
        xn = np.linspace(-1.0, 1.0, N)
        return np.cos(0.5 * np.pi * np.clip(xn / alpha, -1, 1)) ** 2

    for N in Ns:
        if time.process_time() - t0 > deadline * 0.5:
            break
        # seeds
        seeds = []
        if start is not None and np.asarray(start).size > 0:
