import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _objective(x, N, p):
    h = np.exp(x - np.max(x))
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return 1e10
    h = h / s
    conv = np.convolve(h, h)
    m = np.max(np.abs(conv))
    if m <= 0:
        return 1e10
    return np.sum((conv / m) ** p) ** (1.0 / p) * m


def _polish(h, t0, budget):
    """Exact-C coordinate descent with multiplicative factors."""
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h /= s
    best_C = _C(h)
    factors = [0.8, 0.9, 0.95, 1.05, 1.1, 1.2]
    N = len(h)
    for sweep in range(10):
        if time.process_time() - t0 > budget * 0.92:
            break
        improved = False
        for i in range(N):
            if time.process_time() - t0 > budget * 0.92:
                break
            base = h[i]
            best_val = base
            for f in factors:
                h[i] = base * f
                c = _C(h)
                if c < best_C - 1e-15:
                    best_C = c
                    best_val = h[i]
                    improved = True
            h[i] = best_val
        # renormalize
        s = h.sum()
        if s > 0:
            h /= s
        if not improved:
            break
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 80
    p_list = [8, 16, 32, 64, 128]

    best_h = None
    best_C = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            c = _C(s)
            if c < best_C:
                best_C = c
                best_h = s.copy()

    if best_h is None:
        best_h = np.ones(N) / N
        best_C = _C(best_h)

    # Use start's h (resized to N=80 if needed) as init
    h0 = best_h.copy()
    if len(h0) != N:
        # resample to N
        x_old = np.linspace(0, 1, len(h0))
        x_new = np.linspace(0, 1, N)
        h0 = np.interp(x_new, x_old, h0)
        if h0.sum() <= 0:
            h0 = np.ones(N)
    h0 = np.maximum(h0, 1e-12)
    h0 = h0 / h0.sum()

    x = np.log(h0)

    # Anneal p upward
    for p in p_list:
        if time.process_time() - t0 > budget_seconds * 0.5:
            break
        try:
            res = minimize(
                _objective, x, args=(N, p),
                method='L-BFGS-B',
                options={'maxiter': 200, 'ftol': 1e-14, 'gtol': 1e-12}
            )
            x = res.x
            h = np.exp(x - np.max(x))
            h = h / h.sum()
            c = _C(h)
            if c < best_C:
                best_C = c
                best_h = h.copy()
        except Exception:
            pass

    # Exact-C polishing on best candidate
    if time.process_time() - t0 < budget_seconds * 0.92:
        h_pol = _polish(best_h, t0, budget_seconds)
        c = _C(h_pol)
        if c < best_C:
            best_C = c
            best_h = h_pol

    # Also polish the annealed result if different
    if time.process_time() - t0 < budget_seconds * 0.92:
        try:
            h_ann = np.exp(x - np.max(x))
            h_ann = h_ann / h_ann.sum()
            h_pol2 = _polish(h_ann, t0, budget_seconds)
            c = _C(h_pol2)
            if c < best_C:
                best_C = c
                best_h = h_pol2
        except Exception:
            pass

    best_h = np.asarray(best_h, dtype=float)
    best_h = np.where(np.isfinite(best_h) & (best_h >= 0), best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(N)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if _C(s) < _C(best_h):
                best_h = s.copy()

    return best_h

