import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _objective(x, p):
    h = np.exp(x)
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return 1e10
    h = h / s
    conv = np.convolve(h, h)
    m = np.max(np.abs(conv))
    if m <= 0:
        return 1e10
    return np.sum((conv / m) ** p) ** (1.0 / p) * m


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = len(h)
    if M == N:
        return h.copy()
    # step centers in [-1/4, 1/4] for M and N
    xm = (np.arange(M) + 0.5) / M
    xn = (np.arange(N) + 0.5) / N
    out = np.interp(xn, xm, h)
    out = np.maximum(out, 0.0)
    if out.sum() <= 0:
        out = np.ones(N)
    return out


def _opt_from(h0, p, deadline, maxiter=300):
    x0 = np.log(np.maximum(h0, 1e-12))
    try:
        res = minimize(
            _objective, x0, args=(p,),
            method='L-BFGS-B',
            options={'maxiter': maxiter, 'ftol': 1e-14, 'gtol': 1e-12}
        )
        x = res.x
    except Exception:
        return None
    if time.process_time() > deadline:
        pass
    h = np.exp(x)
    if not np.all(np.isfinite(h)) or h.sum() <= 0:
        return None
    h = h / h.sum()
    return h


