import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = len(h)
    if M == N:
        return h.copy()
    xm = (np.arange(M) + 0.5) / M
    xn = (np.arange(N) + 0.5) / N
    out = np.interp(xn, xm, h)
    out = np.maximum(out, 0.0)
    if out.sum() <= 0:
        out = np.ones(N)
    return out


def _smoothmax_objective(x, p):
    # h = exp(x), normalized; minimize (sum (conv/max)^p)^(1/p) * max
    # equivalent to a soft-max surrogate for max(conv) / sum(h)^2
    h = np.exp(x - x.max())
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return 1e10
    h = h / s
    conv = np.convolve(h, h)
    m = conv.max()
    if m <= 0:
        return 1e10
    # soft-max via power mean, scaled by N factor
    return float(np.sum((conv / m) ** p) ** (1.0 / p)) * m * 2.0 * len(h)


def _opt(h0, p, maxiter=400):
    x0 = np.log(np.maximum(h0, 1e-12))
    try:
        res = minimize(
            _smoothmax_objective, x0, args=(p,),
            method='L-BFGS-B',
            options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-12}
        )
        x = res.x
    except Exception:
        return None
    h = np.exp(x - x.max())
    if not np.all(np.isfinite(h)) or h.sum() <= 0:
        return None
    return h


def _polish(h, deadline):
    # Direct coordinate descent on heights (log-space) to reduce true C.
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    x = np.log(np.maximum(h, 1e-12))
    curC = _C(h)
    rng = np.random.default_rng(999)
    step = 0.3
    while time.process_time() < deadline:
        improved = False
        order = rng.permutation(N)
        for i in order:
            if time.process_time() >= deadline:
                break
            old = x[i]
            for d in (step, -step):
                x[i] = old + d
                hh = np.exp(x - x.max())
                c = _C(hh)
                if c < curC - 1e-13:
                    curC = c
                    improved = True
                    break
                else:
                    x[i] = old
        if not improved:
            step *= 0.6
            if step < 1e-5:
                break
    h = np.exp(x - x.max())
    return h, _C(h)


