        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            c = _C(s)
            if c < best_C:
                best_C = c
                best_h = s.copy()

    base = best_h if best_h is not None else np.ones(120)

    # Multi-scale refinement: start from base, resample & optimize at increasing N.
    Ns = [len(base), 120, 200, 320, 500, 800, 1300, 2000]
    # dedupe preserving order
    seen = set()
    Ns = [n for n in Ns if not (n in seen or seen.add(n))]

