            if h is None:
                continue
            c = _C(h)
            if c < best_C - 1e-10:
                best_C = c
                best_h = h.copy()
                base = best_h
        # Also try starting from scratch at this N
        if time.process_time() < deadline:
            h = _opt(np.ones(N), 40, maxiter=300)
            if h is not None:
                c = _C(h)
                if c < best_C - 1e-10:
                    best_C = c
                    best_h = h.copy()
                    base = best_h

    if best_h is None:
        best_h = np.ones(120)

    # Final direct polish on the best solution
    if time.process_time() < deadline:
        polished, pc = _polish(best_h, deadline)
        if pc < best_C:
            best_C = pc
            best_h = polished

    best_h = np.asarray(best_h, dtype=float)
    best_h = np.where(np.isfinite(best_h) & (best_h >= 0), best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(120)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if _C(s) < _C(best_h):
                best_h = s.copy()

    return best_h

