def _objective_sym(x, p):
    m = np.exp(x - np.max(x))
    h = np.concatenate([m, m[::-1]])
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return 1e10
    h = h / s
    conv = np.convolve(h, h)
    mx = np.max(conv)
    if mx <= 0:
        return 1e10
    return np.sum((conv / mx) ** p) ** (1.0 / p) * mx


