    m = len(h)
    if m == N:
        return h.copy()
    return np.interp(np.linspace(0, 1, N), np.linspace(0, 1, m), h)


def _polish(h, t0, budget, frac=0.92):
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h /= s
    best_C = _C(h)
    factors = [0.7, 0.85, 0.93, 0.97, 1.03, 1.07, 1.15, 1.3]
    N = len(h)
    for sweep in range(20):
        if time.process_time() - t0 > budget * frac:
            break
        improved = False
        for i in range(N):
            if time.process_time() - t0 > budget * frac:
                break
            base = h[i]
            best_val = base
            for f in factors:
                h[i] = base * f
                c = _C(h)
                if c < best_C - 1e-15:
                    best_C = c
                    best_val = h[i]
                    improved = True
            h[i] = best_val
        s = h.sum()
        if s > 0:
            h /= s
        if not improved:
            break
    return h


