import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _resample(h, N):
    x_old = np.linspace(0, 1, len(h))
    x_new = np.linspace(0, 1, N)
    r = np.interp(x_new, x_old, h)
    if r.sum() <= 0:
        r = np.ones(N)
    return r


def _smooth_obj(x, N, p):
    h = np.exp(x - np.max(x))
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return 1e10
    h = h / s
    conv = np.convolve(h, h)
    m = np.max(conv)
    if m <= 0:
        return 1e10
    return np.sum((conv / m) ** p) ** (1.0 / p) * m * (2.0 * N)


def _anneal(h0, N, p_list, t0, budget):
    h0 = np.maximum(np.asarray(h0, dtype=float), 1e-12)
    h0 = h0 / h0.sum()
    x = np.log(h0 + 1e-12)
    best_h = h0.copy()
    best_C = _C(h0)
    for p in p_list:
        if time.process_time() - t0 > budget:
            break
        try:
            res = minimize(
                _smooth_obj, x, args=(N, p),
                method='L-BFGS-B',
                options={'maxiter': 200, 'ftol': 1e-15, 'gtol': 1e-13}
            )
            x = res.x
            h = np.exp(x - np.max(x))
            h = h / h.sum()
            c = _C(h)
            if c < best_C:
                best_C = c
                best_h = h.copy()
        except Exception:
            pass
    return best_h, best_C


def _polish(h, t0, budget, factors=None, max_sweeps=30):
    if factors is None:
        factors = [0.7, 0.85, 0.93, 0.97, 1.03, 1.07, 1.15, 1.3]
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h /= s
    best_C = _C(h)
    N = len(h)
    for sweep in range(max_sweeps):
        if time.process_time() - t0 > budget:
            break
        improved = False
        for i in range(N):
            if time.process_time() - t0 > budget:
                break
            base = h[i]
            best_val = base
            for f in factors:
                h[i] = base * f
                c = _C(h)
                if c < best_C - 1e-15:
                    best_C = c
                    best_val = h[i]
                    improved = True
            h[i] = best_val
        s = h.sum()
        if s > 0:
            h /= s
        if not improved:
            break
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    # leave a margin
    deadline = budget_seconds - 1.5

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            base_h = s.copy()
        else:
            base_h = np.ones(80)
    else:
        base_h = np.ones(80)

    best_h = base_h.copy()
    best_C = _C(best_h)

    factors = [0.6, 0.75, 0.85, 0.92, 0.96, 0.98, 1.02, 1.04, 1.08, 1.15, 1.25, 1.5]

    # Stage A: anneal+polish at start's N
    hA, cA = _anneal(best_h, len(best_h), [16, 32, 64, 128], t0, deadline * 0.20)
    if cA < best_C:
        best_C, best_h = cA, hA.copy()
    hA = _polish(best_h, t0, deadline * 0.25, factors=factors, max_sweeps=15)
    cA = _C(hA)
    if cA < best_C:
        best_C, best_h = cA, hA.copy()

    # Stage B: upsample and refine at higher resolution
    # Try two resolutions and keep the better
    for target_N in [len(best_h) * 2, len(best_h) * 4]:
        if time.process_time() - t0 > deadline * 0.70:
            break
        Nn = min(int(target_N), 30000)
        if Nn <= len(best_h):
            continue
        hUp = _resample(best_h, Nn)
        cUp = _C(hUp)
        # anneal at new resolution
        hUp, cUp2 = _anneal(hUp, Nn, [32, 64, 128, 256], t0, deadline * 0.55)
        if cUp2 < best_C:
            best_C, best_h = cUp2, hUp.copy()
        # polish at new resolution
        hUp = _polish(best_h, t0, deadline * 0.65, factors=factors, max_sweeps=12)
        cUp3 = _C(hUp)
        if cUp3 < best_C:
            best_C, best_h = cUp3, hUp.copy()

    # Stage C: final anneal at current N with sharp p
    if time.process_time() - t0 < deadline * 0.90:
        hF, cF = _anneal(best_h, len(best_h), [64, 128, 256, 512], t0, deadline * 0.92)
        if cF < best_C:
            best_C, best_h = cF, hF.copy()

    # Stage D: final polish
    if time.process_time() - t0 < deadline:
        hF = _polish(best_h, t0, deadline, factors=factors, max_sweeps=10)
        cF = _C(hF)
        if cF < best_C:
            best_C, best_h = cF, hF.copy()

    # Final safety: keep start if better
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if _C(s) < _C(best_h):
                best_h = s.copy()

    best_h = np.asarray(best_h, dtype=float)
    best_h = np.where(np.isfinite(best_h) & (best_h >= 0), best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(80)
    if best_h.size > 30000:
        idx = np.linspace(0, best_h.size, 30000, endpoint=False).astype(int)
        best_h = best_h[idx]
    return best_h

