    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _conv_and_grad(h):
    return np.convolve(h, h)


def _lse_objective_grad(x, N, beta):
    xc = x - np.max(x)
    h = np.exp(xc)
    s = h.sum()
    h = h / s
    conv = np.convolve(h, h)
    m = np.max(conv)
    z = beta * (conv - m)
    ez = np.exp(z)
    Z = ez.sum()
    g = (1.0 / beta) * (np.log(Z) + beta * m)
    w = ez / Z
    grad_h = 2.0 * np.correlate(w, h, mode='valid')
    dot = np.dot(grad_h, h)
    grad_x = h * (grad_h - dot)
    return g, grad_x


def _lse_smooth(h0, betas, t0, budget):
    h0 = np.maximum(np.asarray(h0, dtype=float), 1e-14)
    h0 = h0 / h0.sum()
    x = np.log(h0)
    N = len(h0)
    best_h = h0.copy()
    best_C = _C(h0)
    for beta in betas:
        if time.process_time() - t0 > budget:
            break
        try:
            res = minimize(
                _lse_objective_grad, x, args=(N, beta),
                jac=True, method='L-BFGS-B',
                options={'maxiter': 800, 'ftol': 1e-20, 'gtol': 1e-16}
            )
            x = res.x
            h = np.exp(x - np.max(x))
            h = h / h.sum()
            c = _C(h)
            if c < best_C:
                best_C = c
                best_h = h.copy()
        except Exception:
            pass
    return best_h, best_C


