def _slsqp_minimax(h0, t0, budget, maxiter=500):
    """Exact constrained minimax: minimize t s.t. sum(h)=1, h>=0, conv_k(h)<=t."""
    h0 = np.asarray(h0, dtype=float).copy()
    s = h0.sum()
    if s <= 0:
        return h0
    h0 = h0 / s
    N = len(h0)
    K = 2 * N - 1

    lo = np.maximum(0, np.arange(K) - N + 1)
    hi = np.minimum(N - 1, np.arange(K))

    conv0 = np.convolve(h0, h0)
    t_init = float(np.max(conv0)) + 1e-6
    z0 = np.concatenate([h0, [t_init]])

    def obj(z):
        return z[N]

    def jac_obj(z):
        g = np.zeros(N + 1)
        g[N] = 1.0
        return g

    def cons_eq(z):
        return np.array([z[:N].sum() - 1.0])

    def jac_eq(z):
        return np.concatenate([np.ones(N), [0.0]]).reshape(1, -1)

    def cons_ineq(z):
        h = z[:N]
        return z[N] - np.convolve(h, h)

    def jac_ineq(z):
        h = z[:N]
        J = np.zeros((K, N + 1))
        for k in range(K):
            j_lo = lo[k]
            j_hi = hi[k]
            if j_hi >= j_lo:
                js = np.arange(j_lo, j_hi + 1)
                J[k, js] = -2.0 * h[k - js]
            J[k, N] = 1.0
        return J

    bounds = [(0.0, None)] * N + [(0.0, None)]
    constraints = [
        {'type': 'eq', 'fun': cons_eq, 'jac': jac_eq},
        {'type': 'ineq', 'fun': cons_ineq, 'jac': jac_ineq},
    ]

    try:
        res = minimize(
            obj, z0, jac=jac_obj, method='SLSQP',
            bounds=bounds, constraints=constraints,
            options={'maxiter': maxiter, 'ftol': 1e-14}
        )
        z = res.x
        h = np.maximum(z[:N], 0.0)
        st = h.sum()
        if st <= 0:
            return h0
        return h / st
    except Exception:
        return h0


def _upsample_linear(h, Nnew):
    h = np.asarray(h, dtype=float)
    Nold = len(h)
    if Nold == Nnew:
        return h.copy()
    xold = (np.arange(Nold) + 0.5) / Nold
    xnew = (np.arange(Nnew) + 0.5) / Nnew
    return np.interp(xnew, xold, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            base_h = s.copy()
        else:
            base_h = np.ones(80) / 80
    else:
        base_h = np.ones(80) / 80

    best_h = base_h.copy()
    best_C = _C(best_h)

    # Upsample to N=480 for a finer representation.
    N2 = 480
    h2 = _upsample_linear(base_h, N2)
    h2 = np.maximum(h2, 0)
    if h2.sum() <= 0:
        h2 = np.ones(N2)
    h2 = h2 / h2.sum()

    # Stage 1: SLSQP minimax -- exact first-order solve.
    hQ = _slsqp_minimax(h2, t0, budget * 0.5, maxiter=400)
    cQ = _C(hQ)
    if cQ < best_C:
        best_C = cQ
        best_h = hQ.copy()
        h2 = hQ.copy()

    # Stage 2: LSE smoothing at higher betas to squeeze out slack.
    if time.process_time() - t0 < budget * 0.75:
        betas = [500, 2000, 8000, 30000, 100000]
        hS, cS = _lse_smooth(h2, betas, t0, budget * 0.75)
        if cS < best_C:
            best_C = cS
            best_h = hS.copy()
            h2 = hS.copy()

    # Stage 3: SLSQP again on refined iterate.
    if time.process_time() - t0 < budget * 0.92:
        hQ = _slsqp_minimax(h2, t0, budget * 0.92, maxiter=400)
        cQ = _C(hQ)
        if cQ < best_C:
            best_C = cQ
            best_h = hQ.copy()
            h2 = hQ.copy()

    # Stage 4: coordinate polish.
    if time.process_time() - t0 < budget * 0.98:
        hP = _polish(h2, t0, budget * 0.98, max_sweeps=5)
        cP = _C(hP)
        if cP < best_C:
            best_C = cP
            best_h = hP.copy()

    # Final safety: keep start if better.
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if _C(s) < _C(best_h):
                best_h = s.copy()

    best_h = np.asarray(best_h, dtype=float)
    best_h = np.where(np.isfinite(best_h) & (best_h >= 0), best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(80)
    return best_h

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _reduced_hessian(h, support_mask):
    N = len(h)
    K = 2 * N - 1
    conv = np.convolve(h, h)
    mx = np.max(conv)
    near = np.where(conv >= mx - 1e-10 * mx)[0]
    if len(near) == 0:
        near = np.array([np.argmax(conv)])
    idx = np.where(support_mask)[0]
    nS = len(idx)
    g = np.zeros(nS)
    for col, i in enumerate(idx):
        acc = 0.0
        for k in near:
            j = k - i
            if 0 <= j < N:
                acc += 2.0 * h[j]
        g[col] = acc
    g = g - g.mean()
    near_set = set(near.tolist())
    H = np.zeros((nS, nS))
    for a, i in enumerate(idx):
        for b, j in enumerate(idx):
            s = i + j
            if 0 <= s < K and s in near_set:
                H[a, b] += 2.0
    P = np.eye(nS) - np.ones((nS, nS)) / nS
    H = P @ H @ P
    return g, H


def _qnewton_kk(h, t0, budget, max_iter=200, tol=1e-14):
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h = h / s
    best_h = h.copy()
    best_C = _C(h)

    for it in range(max_iter):
        if time.process_time() - t0 > budget:
            break
        support = h > 1e-13
        if not np.any(support):
            break
        idx = np.where(support)[0]
        nS = len(idx)
        if nS < 2:
            break
        g, H = _reduced_hessian(h, support)
        try:
            reg = 1e-10 * (np.trace(H) / max(nS, 1) + 1e-14)
            dx = np.linalg.solve(H + reg * np.eye(nS), -g)
        except np.linalg.LinAlgError:
            try:
                dx, *_ = np.linalg.lstsq(H, -g, rcond=None)
            except Exception:
                break
        if not np.all(np.isfinite(dx)):
            break
        best_alpha = 0.0
        best_alpha_C = best_C
        for alpha in [1.0, 0.5, 0.25, 0.1, 0.05, 0.02, 0.01]:
            h_try = h.copy()
            h_try[idx] = h[idx] + alpha * dx
            if np.any(h_try < -1e-15):
                h_try = np.maximum(h_try, 0.0)
            st = h_try.sum()
            if st <= 0:
                continue
            h_try = h_try / st
            c = _C(h_try)
            if c < best_alpha_C - 1e-16:
                best_alpha_C = c
                best_alpha = alpha
        if best_alpha <= 0:
            break
        h_try = h.copy()
        h_try[idx] = h[idx] + best_alpha * dx
        h_try = np.maximum(h_try, 0.0)
        st = h_try.sum()
        if st <= 0:
            break
        h = h_try / st
        c = _C(h)
        if c < best_C - 1e-16:
            best_C = c
            best_h = h.copy()
        else:
            break
        if np.max(np.abs(dx)) < tol:
            break
    return best_h


def _polish(h, t0, budget, factors=None, max_sweeps=30):
    if factors is None:
        factors = [0.5, 0.7, 0.85, 0.93, 0.97, 0.99, 1.01, 1.03, 1.07, 1.15, 1.3, 1.5]
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h /= s
    best_C = _C(h)
    N = len(h)
    for sweep in range(max_sweeps):
        if time.process_time() - t0 > budget:
            break
        improved = False
        for i in range(N):
            if time.process_time() - t0 > budget:
                break
            base = h[i]
            best_val = base
            for f in factors:
                h[i] = base * f
                c = _C(h)
                if c < best_C - 1e-16:
                    best_C = c
                    best_val = h[i]
                    improved = True
            h[i] = best_val
        s = h.sum()
        if s > 0:
            h /= s
        if not improved:
            break
    return h


def _resize_smooth(h, N_new):
    N = len(h)
    if N == N_new:
        return h.copy()
    h = np.asarray(h, dtype=float)
    cum = np.concatenate([[0.0], np.cumsum(h)])
    cum = cum / cum[-1]
    edges_old = np.arange(N + 1) / N
    new_edges = np.arange(N_new + 1) / N_new
    mass = np.interp(new_edges, edges_old, cum)
    out = np.diff(mass) * N_new
    out = np.maximum(out, 0.0)
    if out.sum() <= 0:
        return np.ones(N_new)
    return out / out.sum() * N_new


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.95

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
