    best_h = base_h.copy()
    best_C = _C(best_h)

    # Stage A: refine at N=900 (70% of budget)
    h900 = _resize_smooth(best_h, 900)
    h900 = _qnewton_kk(h900, t0, budget * 0.70, max_iter=400)
    c900 = _C(h900)
    if c900 < best_C:
        best_C = c900
        best_h = h900.copy()

    # Stage B: refine at N=1500 if time permits
    if time.process_time() - t0 < budget * 0.85:
        h1500 = _resize_smooth(best_h, 1500)
