        c1500 = _C(h1500)
        if c1500 < best_C:
            best_C = c1500
            best_h = h1500.copy()

    # Stage C: final polish
    if time.process_time() - t0 < budget:
        hP = _polish(best_h, t0, budget, max_sweeps=20)
        cP = _C(hP)
        if cP < best_C:
            best_C = cP
            best_h = hP.copy()

    # Safety: keep best of start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if _C(s) < _C(best_h):
