        try:
            reg = 1e-10 * (np.trace(H) / max(nS, 1) + 1e-14)
            dx = np.linalg.solve(H + reg * np.eye(nS), -g)
        except np.linalg.LinAlgError:
            try:
                dx, *_ = np.linalg.lstsq(H, -g, rcond=None)
            except Exception:
                break
        if not np.all(np.isfinite(dx)):
            break
        best_alpha = 0.0
        best_alpha_C = best_C
        for alpha in [1.0, 0.5, 0.25, 0.1, 0.05, 0.02, 0.01]:
            h_try = h.copy()
            h_try[idx] = h[idx] + alpha * dx
            if np.any(h_try < -1e-15):
                h_try = np.maximum(h_try, 0.0)
            st = h_try.sum()
            if st <= 0:
                continue
            h_try = h_try / st
            c = _C(h_try)
            if c < best_alpha_C - 1e-16:
                best_alpha_C = c
                best_alpha = alpha
        if best_alpha <= 0:
            break
        h_try = h.copy()
        h_try[idx] = h[idx] + best_alpha * dx
        h_try = np.maximum(h_try, 0.0)
        st = h_try.sum()
        if st <= 0:
            break
        h = h_try / st
        c = _C(h)
        if c < best_C - 1e-16:
            best_C = c
            best_h = h.copy()
        else:
            break
        if np.max(np.abs(dx)) < tol:
            break
    return best_h


def _polish(h, t0, budget, factors=None, max_sweeps=30):
    if factors is None:
        factors = [0.5, 0.7, 0.85, 0.93, 0.97, 0.99, 1.01, 1.03, 1.07, 1.15, 1.3, 1.5]
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h /= s
    best_C = _C(h)
    N = len(h)
    for sweep in range(max_sweeps):
        if time.process_time() - t0 > budget:
            break
        improved = False
        for i in range(N):
            if time.process_time() - t0 > budget:
                break
            base = h[i]
            best_val = base
            for f in factors:
                h[i] = base * f
                c = _C(h)
                if c < best_C - 1e-16:
                    best_C = c
                    best_val = h[i]
                    improved = True
            h[i] = best_val
        s = h.sum()
        if s > 0:
            h /= s
        if not improved:
            break
    return h


def _cos_basis(N, J=13):
    x = -0.25 + (np.arange(N) + 0.5) / N
    B = np.zeros((N, J))
    for j in range(J):
        B[:, j] = np.cos(4.0 * np.pi * j * x)
    return B


def _h_from_a(a, B):
    h = B @ a
    return np.maximum(h, 0.0)


def _cos_opt(B, a0, t0, budget, maxfev=4000):
    def obj(a):
        h = _h_from_a(a, B)
        return _C(h)
    try:
        res = minimize(obj, a0, method='Powell',
                       options={'maxfev': maxfev, 'xtol': 1e-10, 'ftol': 1e-12})
        return res.x, res.fun
    except Exception:
        return a0, obj(a0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.95

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            base_h = s.copy()
        else:
            base_h = np.ones(300) / 300
    else:
        base_h = np.ones(300) / 300

    best_h = base_h.copy()
    best_C = _C(best_h)

    N = 300
    J = 13
    B = _cos_basis(N, J)

    # Fourier projection of start onto cosine basis (least squares)
    hs = np.asarray(base_h, dtype=float)
    if len(hs) != N:
        x_old = -0.25 + (np.arange(len(hs)) + 0.5) / len(hs)
        x_new = -0.25 + (np.arange(N) + 0.5) / N
        hs = np.interp(x_new, x_old, hs)
    hs = np.maximum(hs, 0.0)
    try:
        a_proj, *_ = np.linalg.lstsq(B, hs, rcond=None)
    except Exception:
        a_proj = np.zeros(J)
        a_proj[0] = 1.0

    rng = np.random.RandomState(12345)
    inits = [a_proj.copy()]
    scale0 = max(np.max(np.abs(a_proj)), 1e-3)
    for _ in range(5):
        a_r = a_proj + rng.randn(J) * 0.3 * scale0
        inits.append(a_r)

    # Stage 1: Powell from multiple inits
    cos_budget = t0 + budget * 0.55
    best_a = a_proj.copy()
    best_a_C = _C(_h_from_a(a_proj, B))
    for k, a0 in enumerate(inits):
        if time.process_time() > cos_budget:
            break
        a_opt, c_opt = _cos_opt(B, a0, t0, cos_budget)
        if c_opt < best_a_C:
            best_a_C = c_opt
            best_a = a_opt.copy()
        h_try = _h_from_a(a_opt, B)
        if _C(h_try) < best_C:
            best_C = _C(h_try)
            best_h = h_try.copy()

    # Build best smooth h
    h_cos = _h_from_a(best_a, B)
    if h_cos.sum() <= 0:
        h_cos = np.ones(N)
    h_cos = h_cos / h_cos.sum() * N
    c_cos = _C(h_cos)
    print("cos best C =", c_cos)
    if c_cos < best_C:
        best_C = c_cos
        best_h = h_cos.copy()

    # Stage 2: Newton refinement on the smooth (and possibly best) h
    if time.process_time() - t0 < budget * 0.75:
        hK = _qnewton_kk(best_h, t0, budget * 0.75, max_iter=100)
        cK = _C(hK)
        if cK < best_C:
            best_C = cK
            best_h = hK.copy()

    # Stage 3: polish
    if time.process_time() - t0 < budget * 0.90:
        hP = _polish(best_h, t0, budget * 0.90, max_sweeps=20)
        cP = _C(hP)
        if cP < best_C:
            best_C = cP
            best_h = hP.copy()

    # Stage 4: final Newton + polish
    if time.process_time() - t0 < budget:
        hK = _qnewton_kk(best_h, t0, budget, max_iter=50)
        cK = _C(hK)
        if cK < best_C:
            best_C = cK
            best_h = hK.copy()
    if time.process_time() - t0 < budget:
        hP = _polish(best_h, t0, budget, max_sweeps=10)
        cP = _C(hP)
        if cP < best_C:
            best_C = cP
            best_h = hP.copy()

    # Keep best of start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if _C(s) < _C(best_h):
                best_h = s.copy()

    best_h = np.asarray(best_h, dtype=float)
    best_h = np.where(np.isfinite(best_h) & (best_h >= 0), best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(300)
    print("final C =", _C(best_h), "N =", len(best_h))
    return best_h

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _conv_max(h):
    return float(np.max(np.convolve(h, h)))


def _kkt_newton(h, t0, budget, n_iter=60, tol=1e-13):
    """Newton on KKT of: maximize lambda s.t. conv_i(h) <= lambda for active i,
    with sum h = 1, h>=0. Works in the reduced space of the active support."""
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h = h / s
    N = len(h)
    best_h = h.copy()
    best_C = _C(h)

    for it in range(n_iter):
        if time.process_time() - t0 > budget:
            break
        conv = np.convolve(h, h)
        mx = np.max(conv)
        A = np.where(conv >= mx - tol * mx)[0]
        S = np.where(h > 1e-13)[0]
        nS = len(S)
        if nS == 0 or len(A) == 0:
            break

        pos_in_S = -np.ones(N, dtype=int)
        pos_in_S[S] = np.arange(nS)

        n_eq = nS + 1
        r = np.zeros(n_eq)
        J = np.zeros((n_eq, nS + 1))
        accs = np.zeros(nS)
        for ri, i in enumerate(S):
            acc = 0.0
            for k in A:
                j = k - i
                if 0 <= j < N:
                    pj = pos_in_S[j]
                    if pj >= 0:
                        acc += 2.0 * h[j]
                        J[ri, pj] += 2.0
            accs[ri] = acc
            J[ri, nS] = -1.0
        lam = accs.mean()
        r[:nS] = accs - lam
        r[nS] = h[S].sum() - 1.0
        J[nS, :nS] = 1.0

        try:
            du = np.linalg.solve(J, -r)
        except np.linalg.LinAlgError:
            try:
                du, *_ = np.linalg.lstsq(J, -r, rcond=None)
            except Exception:
                break

        dh_S = du[:nS]
        best_alpha = 0.0
        best_alpha_C = best_C
        for alpha in [1.0, 0.7, 0.5, 0.3, 0.1, 0.03, 0.01]:
            h_try = h.copy()
            h_try[S] = h[S] + alpha * dh_S
            h_try = np.maximum(h_try, 0.0)
            st = h_try.sum()
            if st <= 0:
                continue
            h_try = h_try / st
            c = _C(h_try)
            if c < best_alpha_C - 1e-16:
                best_alpha_C = c
                best_alpha = alpha
        if best_alpha <= 0:
            h_try = h.copy()
            h_try[S] = h[S] + dh_S
            h_try = np.maximum(h_try, 0.0)
            st = h_try.sum()
            if st > 0:
                h_try = h_try / st
                c = _C(h_try)
                if c <= best_C + 1e-12:
                    h = h_try
                    if c < best_C:
                        best_C = c
                        best_h = h.copy()
                    continue
            break

        h = h.copy()
        h[S] = h[S] + best_alpha * dh_S
        h = np.maximum(h, 0.0)
        st = h.sum()
        if st <= 0:
            break
        h = h / st
        c = _C(h)
        if c < best_C - 1e-16:
            best_C = c
            best_h = h.copy()
        else:
            if np.max(np.abs(r[:nS])) < 1e-12 and abs(r[nS]) < 1e-12:
                break
    return best_h


def _polish(h, t0, budget, max_sweeps=40):
    factors = [0.6, 0.8, 0.9, 0.95, 0.98, 1.02, 1.05, 1.1, 1.25, 1.5]
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h /= s
    best_C = _C(h)
    N = len(h)
    for sweep in range(max_sweeps):
        if time.process_time() - t0 > budget:
            break
        improved = False
        for i in range(N):
            if time.process_time() - t0 > budget:
                break
            base = h[i]
            best_val = base
            for f in factors:
                h[i] = base * f
                c = _C(h)
                if c < best_C - 1e-15:
                    best_C = c
                    best_val = h[i]
                    improved = True
            h[i] = best_val
        s = h.sum()
        if s > 0:
            h /= s
        if not improved:
            break
    return h


def _upsample(h, N_new):
    """Resample a step-function height array to a new resolution."""
    h = np.asarray(h, dtype=float)
    N_old = len(h)
    if N_old == N_new:
        return h.copy()
    x_old = (np.arange(N_old) + 0.5) / N_old
    x_new = (np.arange(N_new) + 0.5) / N_new
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            base_h = s.copy()
        else:
            base_h = np.ones(240) / 240
    else:
        base_h = np.ones(240) / 240

    best_h = base_h.copy()
    best_C = _C(best_h)

    # Stage 1: KKT Newton on start (refine at native resolution)
    if time.process_time() - t0 < budget * 0.25:
        try:
            hK = _kkt_newton(best_h, t0, budget * 0.25, n_iter=80, tol=1e-13)
            cK = _C(hK)
            if cK < best_C - 1e-15:
                best_C = cK
                best_h = hK.copy()
        except Exception:
            pass

    # Stage 2: Upsample to higher resolution and refine
    for N_try in [480, 960]:
        if time.process_time() - t0 > budget * 0.55:
            break
        h_up = _upsample(best_h, N_try)
        h_up = np.maximum(h_up, 0.0)
        st = h_up.sum()
        if st <= 0:
            continue
        h_up /= st
        c_up = _C(h_up)
        if c_up < best_C:
            best_C = c_up
            best_h = h_up.copy()
        try:
            sub_budget = budget * (0.55 if N_try == 480 else 0.75)
            hK = _kkt_newton(best_h, t0, sub_budget, n_iter=60, tol=1e-13)
            cK = _C(hK)
            if cK < best_C - 1e-15:
                best_C = cK
                best_h = hK.copy()
        except Exception:
            pass

    # Stage 3: polish at current resolution
    if time.process_time() - t0 < budget * 0.85:
        hP = _polish(best_h, t0, budget * 0.85, max_sweeps=30)
        cP = _C(hP)
        if cP < best_C:
            best_C = cP
            best_h = hP.copy()

    # Stage 4: final KKT
    if time.process_time() - t0 < budget * 0.95:
        try:
            hK = _kkt_newton(best_h, t0, budget * 0.95, n_iter=40, tol=1e-14)
            cK = _C(hK)
            if cK < best_C - 1e-15:
                best_C = cK
                best_h = hK.copy()
        except Exception:
            pass

    # Stage 5: last polish
    if time.process_time() - t0 < budget * 0.99:
        hP = _polish(best_h, t0, budget * 0.99, max_sweeps=10)
        cP = _C(hP)
        if cP < best_C:
            best_C = cP
            best_h = hP.copy()

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if _C(s) < _C(best_h):
                best_h = s.copy()

    best_h = np.asarray(best_h, dtype=float)
    best_h = np.where(np.isfinite(best_h) & (best_h >= 0), best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(240)
    print("final C =", _C(best_h), "N =", len(best_h))
    return best_h

import numpy as np
import time
from scipy.optimize import minimize, differential_evolution


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _reduced_hessian(h, support_mask):
    N = len(h)
    K = 2 * N - 1
    conv = np.convolve(h, h)
    mx = np.max(conv)
    near = np.where(conv >= mx - 1e-10 * mx)[0]
    if len(near) == 0:
        near = np.array([np.argmax(conv)])
    idx = np.where(support_mask)[0]
    nS = len(idx)
    g = np.zeros(nS)
    for col, i in enumerate(idx):
        acc = 0.0
        for k in near:
            j = k - i
            if 0 <= j < N:
                acc += 2.0 * h[j]
        g[col] = acc
    g = g - g.mean()
    H = np.zeros((nS, nS))
    near_set = set(near.tolist())
    for a, i in enumerate(idx):
        for b, j in enumerate(idx):
            s = i + j
            if 0 <= s < K and s in near_set:
                H[a, b] += 2.0
    P = np.eye(nS) - np.ones((nS, nS)) / nS
    H = P @ H @ P
    return g, H


def _qnewton_kk(h, t0, budget, max_iter=200, tol=1e-14):
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h = h / s
    N = len(h)
    best_h = h.copy()
    best_C = _C(h)

    for it in range(max_iter):
        if time.process_time() - t0 > budget:
            break
        support = h > 1e-13
        if not np.any(support):
            break
        idx = np.where(support)[0]
        nS = len(idx)
        if nS < 2:
            break
        g, H = _reduced_hessian(h, support)
        try:
            reg = 1e-10 * (np.trace(H) / max(nS, 1) + 1e-14)
            dx = np.linalg.solve(H + reg * np.eye(nS), -g)
        except np.linalg.LinAlgError:
            try:
                dx, *_ = np.linalg.lstsq(H, -g, rcond=None)
            except Exception:
                break
        if not np.all(np.isfinite(dx)):
            break
        best_alpha = 0.0
        best_alpha_C = best_C
        for alpha in [1.0, 0.5, 0.25, 0.1, 0.05, 0.02, 0.01]:
            h_try = h.copy()
            h_try[idx] = h[idx] + alpha * dx
            if np.any(h_try < -1e-15):
                h_try = np.maximum(h_try, 0.0)
            st = h_try.sum()
            if st <= 0:
                continue
            h_try = h_try / st
            c = _C(h_try)
            if c < best_alpha_C - 1e-16:
                best_alpha_C = c
                best_alpha = alpha
        if best_alpha <= 0:
            break
        h_try = h.copy()
        h_try[idx] = h[idx] + best_alpha * dx
        h_try = np.maximum(h_try, 0.0)
        st = h_try.sum()
        if st <= 0:
            break
        h = h_try / st
        c = _C(h)
        if c < best_C - 1e-16:
            best_C = c
            best_h = h.copy()
        else:
            break
        if np.max(np.abs(dx)) < tol:
            break
    return best_h


def _polish(h, t0, budget, factors=None, max_sweeps=30):
    if factors is None:
        factors = [0.5, 0.7, 0.85, 0.93, 0.97, 0.99, 1.01, 1.03, 1.07, 1.15, 1.3, 1.5]
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h /= s
    best_C = _C(h)
    N = len(h)
    for sweep in range(max_sweeps):
        if time.process_time() - t0 > budget:
            break
        improved = False
        for i in range(N):
            if time.process_time() - t0 > budget:
                break
            base = h[i]
            best_val = base
            for f in factors:
                h[i] = base * f
                c = _C(h)
                if c < best_C - 1e-16:
                    best_C = c
                    best_val = h[i]
                    improved = True
            h[i] = best_val
        s = h.sum()
        if s > 0:
            h /= s
        if not improved:
            break
    return h


def _knots(N, K):
    # K control points at equally spaced indices including endpoints
    return np.linspace(0, N - 1, K)


def _h_from_ctrl(ctrl, N, knots):
    x = np.arange(N)
    return np.maximum(np.interp(x, knots, ctrl), 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.95

    N = 300
    K = 15
    knots = _knots(N, K)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            base_h = s.copy()
        else:
            base_h = np.ones(N) / N
    else:
        base_h = np.ones(N) / N

    # Resample start to N
    hs = np.asarray(base_h, dtype=float)
    if len(hs) != N:
        x_old = -0.25 + (np.arange(len(hs)) + 0.5) / len(hs)
        x_new = -0.25 + (np.arange(N) + 0.5) / N
        hs = np.interp(x_new, x_old, hs)
    hs = np.maximum(hs, 0.0)
    if hs.sum() <= 0:
        hs = np.ones(N)

    best_h = hs.copy()
    best_C = _C(best_h)

    # Initial control values from least-squares fit of start
    # Solve interp as linear: build matrix
    M = np.zeros((N, K))
    for k in range(K):
        e = np.zeros(K)
        e[k] = 1.0
        M[:, k] = np.interp(np.arange(N), knots, e)
    try:
        ctrl0, *_ = np.linalg.lstsq(M, hs, rcond=None)
    except Exception:
        ctrl0 = np.ones(K)
    ctrl0 = np.maximum(ctrl0, 0.0)
    if ctrl0.sum() <= 0:
        ctrl0 = np.ones(K)

    c0 = _C(_h_from_ctrl(ctrl0, N, knots))
    if c0 < best_C:
        best_C = c0
        best_h = _h_from_ctrl(ctrl0, N, knots).copy()

    hmax = max(np.max(hs), 1e-6)
    upper = 3.0 * hmax
    bounds = [(0.0, upper)] * K

    def obj(ctrl):
        h = _h_from_ctrl(ctrl, N, knots)
        return _C(h)

    # Stage 1: differential evolution on control values
    de_budget = t0 + budget * 0.55
    best_ctrl = ctrl0.copy()
    try:
        res = differential_evolution(
            obj, bounds, seed=12345, popsize=20, maxiter=200,
            tol=1e-10, mutation=(0.5, 1.0), recombination=0.7,
            polish=False, init='latinhypercube', updating='immediate',
            workers=1
        )
        if res.fun < obj(best_ctrl):
            best_ctrl = res.x.copy()
    except Exception as e:
        print("DE failed:", e)

    h_de = _h_from_ctrl(best_ctrl, N, knots)
    c_de = _C(h_de)
    print("DE best C =", c_de)
