import numpy as np
import time
from scipy.optimize import minimize, linprog


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _reduced_hessian(h, support_mask):
    N = len(h)
    K = 2 * N - 1
    conv = np.convolve(h, h)
    mx = np.max(conv)
    near = np.where(conv >= mx - 1e-10 * mx)[0]
    if len(near) == 0:
        near = np.array([np.argmax(conv)])
    idx = np.where(support_mask)[0]
    nS = len(idx)
    g = np.zeros(nS)
    for col, i in enumerate(idx):
        acc = 0.0
        for k in near:
            j = k - i
            if 0 <= j < N:
                acc += 2.0 * h[j]
        g[col] = acc
    g = g - g.mean()
    H = np.zeros((nS, nS))
    near_set = set(near.tolist())
    for a, i in enumerate(idx):
        for b, j in enumerate(idx):
            s = i + j
            if 0 <= s < K and s in near_set:
                H[a, b] += 2.0
    P = np.eye(nS) - np.ones((nS, nS)) / nS
    H = P @ H @ P
    return g, H


def _qnewton_kk(h, t0, budget, max_iter=200, tol=1e-14):
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h = h / s
    N = len(h)
    best_h = h.copy()
    best_C = _C(h)

    for it in range(max_iter):
        if time.process_time() - t0 > budget:
            break
        support = h > 1e-13
        if not np.any(support):
            break
        idx = np.where(support)[0]
        nS = len(idx)
        if nS < 2:
            break
        g, H = _reduced_hessian(h, support)
        try:
            reg = 1e-10 * (np.trace(H) / max(nS, 1) + 1e-14)
            dx = np.linalg.solve(H + reg * np.eye(nS), -g)
        except np.linalg.LinAlgError:
            try:
                dx, *_ = np.linalg.lstsq(H, -g, rcond=None)
            except Exception:
                break
        if not np.all(np.isfinite(dx)):
            break
        best_alpha = 0.0
        best_alpha_C = best_C
        for alpha in [1.0, 0.5, 0.25, 0.1, 0.05, 0.02, 0.01]:
            h_try = h.copy()
            h_try[idx] = h[idx] + alpha * dx
            if np.any(h_try < -1e-15):
                h_try = np.maximum(h_try, 0.0)
            st = h_try.sum()
            if st <= 0:
                continue
            h_try = h_try / st
            c = _C(h_try)
            if c < best_alpha_C - 1e-16:
                best_alpha_C = c
                best_alpha = alpha
        if best_alpha <= 0:
            break
        h_try = h.copy()
        h_try[idx] = h[idx] + best_alpha * dx
        h_try = np.maximum(h_try, 0.0)
        st = h_try.sum()
        if st <= 0:
            break
        h = h_try / st
        c = _C(h)
        if c < best_C - 1e-16:
            best_C = c
            best_h = h.copy()
        else:
            break
        if np.max(np.abs(dx)) < tol:
            break
    return best_h


def _polish(h, t0, budget, factors=None, max_sweeps=30):
    if factors is None:
        factors = [0.5, 0.7, 0.85, 0.93, 0.97, 0.99, 1.01, 1.03, 1.07, 1.15, 1.3, 1.5]
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h /= s
    best_C = _C(h)
    N = len(h)
    for sweep in range(max_sweeps):
        if time.process_time() - t0 > budget:
            break
        improved = False
        for i in range(N):
            if time.process_time() - t0 > budget:
                break
            base = h[i]
            best_val = base
            for f in factors:
                h[i] = base * f
                c = _C(h)
                if c < best_C - 1e-16:
                    best_C = c
                    best_val = h[i]
                    improved = True
            h[i] = best_val
        s = h.sum()
        if s > 0:
            h /= s
        if not improved:
            break
    return h


def _cos_basis(N, J=40):
    x = -0.25 + (np.arange(N) + 0.5) / N
    B = np.zeros((N, J))
    for j in range(J):
        B[:, j] = np.cos(4.0 * np.pi * j * x)
    return B


def _h_from_a(a, B):
    h = B @ a
    return np.maximum(h, 0.0)


def _cos_opt(B, a0, t0, budget, maxfev=20000):
    def obj(a):
        h = _h_from_a(a, B)
        return _C(h)
    try:
        res = minimize(obj, a0, method='Powell',
                       options={'maxfev': maxfev, 'xtol': 1e-10, 'ftol': 1e-12})
        return res.x, res.fun
    except Exception:
        return a0, obj(a0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.95

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            base_h = s.copy()
        else:
            base_h = np.ones(300) / 300
    else:
        base_h = np.ones(300) / 300

    best_h = base_h.copy()
    best_C = _C(best_h)

    N = 300
    J = 40
    B = _cos_basis(N, J)

    # Fourier projection of start onto cosine basis (least squares)
    hs = np.asarray(base_h, dtype=float)
    if len(hs) != N:
        x_old = -0.25 + (np.arange(len(hs)) + 0.5) / len(hs)
        x_new = -0.25 + (np.arange(N) + 0.5) / N
        hs = np.interp(x_new, x_old, hs)
    hs = np.maximum(hs, 0.0)
    try:
        a_proj, *_ = np.linalg.lstsq(B, hs, rcond=None)
    except Exception:
        a_proj = np.zeros(J)
        a_proj[0] = 1.0

    rng = np.random.RandomState(12345)
    inits = [a_proj.copy()]
    scale0 = max(np.max(np.abs(a_proj)), 1e-3)
    for _ in range(20):
        a_r = a_proj + rng.randn(J) * 0.5 * scale0
        inits.append(a_r)

    # Stage 1: Powell from multiple inits
    cos_budget = t0 + budget * 0.80
    best_a = a_proj.copy()
    best_a_C = _C(_h_from_a(a_proj, B))
    for k, a0 in enumerate(inits):
        if time.process_time() > cos_budget:
            break
        a_opt, c_opt = _cos_opt(B, a0, t0, cos_budget)
        if c_opt < best_a_C:
            best_a_C = c_opt
            best_a = a_opt.copy()
        h_try = _h_from_a(a_opt, B)
        if _C(h_try) < best_C:
            best_C = _C(h_try)
            best_h = h_try.copy()

    # Build best smooth h
    h_cos = _h_from_a(best_a, B)
    if h_cos.sum() <= 0:
        h_cos = np.ones(N)
    h_cos = h_cos / h_cos.sum() * N
    c_cos = _C(h_cos)
    print("cos best C =", c_cos)
    if c_cos < best_C:
        best_C = c_cos
        best_h = h_cos.copy()

    # Stage 2: Newton refinement on the smooth (and possibly best) h
    if time.process_time() - t0 < budget * 0.90:
        hK = _qnewton_kk(best_h, t0, budget * 0.90, max_iter=100)
        cK = _C(hK)
        if cK < best_C:
            best_C = cK
            best_h = hK.copy()

    # Stage 3: polish
    if time.process_time() - t0 < budget * 0.95:
        hP = _polish(best_h, t0, budget * 0.95, max_sweeps=20)
        cP = _C(hP)
        if cP < best_C:
            best_C = cP
            best_h = hP.copy()

    # Stage 4: final Newton + polish
    if time.process_time() - t0 < budget:
        hK = _qnewton_kk(best_h, t0, budget, max_iter=50)
        cK = _C(hK)
        if cK < best_C:
            best_C = cK
            best_h = hK.copy()
    if time.process_time() - t0 < budget:
        hP = _polish(best_h, t0, budget, max_sweeps=10)
        cP = _C(hP)
        if cP < best_C:
            best_C = cP
            best_h = hP.copy()

    # Keep best of start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if _C(s) < _C(best_h):
                best_h = s.copy()

    best_h = np.asarray(best_h, dtype=float)
    best_h = np.where(np.isfinite(best_h) & (best_h >= 0), best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(300)
    print("final C =", _C(best_h), "N =", len(best_h))
    return best_h

import numpy as np
import time


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _resize(h, N_new):
    N = len(h)
    if N == N_new:
        return np.asarray(h, dtype=float).copy()
    h = np.asarray(h, dtype=float)
    cum = np.concatenate([[0.0], np.cumsum(h)])
    if cum[-1] <= 0:
        return np.ones(N_new)
    cum = cum / cum[-1]
    new_edges = np.arange(N_new + 1) / N_new
    mass = np.interp(new_edges, np.arange(N + 1) / N, cum)
    out = np.diff(mass)
    out = np.maximum(out, 0.0)
    if out.sum() <= 0:
        return np.ones(N_new)
    return out / out.sum() * N_new


def _slsqp_solve(h, t0, budget, maxiter=500):
    """SLSQP on [h, M]: minimize M s.t. conv_k(h) <= M, sum(h)=1, h>=0."""
    from scipy.optimize import minimize
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h = h / s
    N = len(h)
    K = 2 * N - 1

    conv0 = np.convolve(h, h)
    M0 = float(np.max(conv0)) * 1.001 + 1e-12
    x0 = np.concatenate([h, [M0]])

    def obj(x):
        return x[-1]

    def obj_grad(x):
        g = np.zeros(N + 1)
        g[-1] = 1.0
        return g

    def cons_fun(x):
        hh = x[:N]
        M = x[-1]
        c = np.convolve(hh, hh)
        return M - c  # >= 0

    def cons_jac(x):
        hh = x[:N]
        J = np.zeros((K, N + 1))
        # d/dh_i of (M - conv_k) = -2 h_{k-i}
        for k in range(K):
            lo = max(0, k - (N - 1))
            hi = min(N - 1, k)
            for i in range(lo, hi + 1):
                j = k - i
                if 0 <= j < N:
                    J[k, i] += -2.0 * hh[j]
            J[k, N] = 1.0
        return J

    def sum_fun(x):
        return x[:N].sum() - 1.0

    def sum_jac(x):
        g = np.zeros(N + 1)
        g[:N] = 1.0
        return g

    bounds = [(0.0, None)] * N + [(0.0, None)]
    constraints = [
        {'type': 'ineq', 'fun': cons_fun, 'jac': cons_jac},
        {'type': 'eq', 'fun': sum_fun, 'jac': sum_jac},
    ]

    def cb(xk):
        if time.process_time() - t0 > budget:
            raise StopIteration

    try:
        res = minimize(obj, x0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=constraints,
                       options={'ftol': 1e-12, 'maxiter': maxiter, 'disp': False},
                       callback=cb)
        xf = res.x
    except StopIteration:
        return h
    except Exception:
        return h

    hf = np.maximum(xf[:N], 0.0)
    if hf.sum() <= 0:
        return h
    hf = hf / hf.sum()
    return hf


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.90

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            base_h = s.copy()
        else:
            base_h = np.ones(300) / 300
    else:
        base_h = np.ones(300) / 300

    best_h = np.asarray(base_h, dtype=float).copy()
    best_C = _C(best_h)

    # Stage 1: SLSQP at N=300
    if time.process_time() - t0 < budget * 0.55:
        h300 = _resize(best_h, 300)
