def _bspline_basis(x, knots, J, degree=3):
    """Evaluate B-spline basis of J control points on knots at points x.
    Returns array shape (len(x), J)."""
    n = len(knots) - degree - 1  # number of basis functions
    # Cox-de Boor
    x = np.asarray(x, dtype=float)
    # clamp to [knots[degree], knots[n]]
    x = np.clip(x, knots[degree], knots[n] - 1e-15)
    B = np.zeros((len(x), n))
    # degree 0
    for i in range(n + degree):
        if i + 1 < len(knots):
            lo, hi = knots[i], knots[i + 1]
            if i < n:
                B[:, i] = ((x >= lo) & (x < hi)).astype(float)
    # last point
    B[x >= knots[n], n - 1] = 1.0
    # recursion
    for d in range(1, degree + 1):
        Bnew = np.zeros((len(x), n))
        for i in range(n):
            denom1 = knots[i + d] - knots[i]
            denom2 = knots[i + d + 1] - knots[i + 1]
            t1 = 0.0
            t2 = 0.0
            if denom1 > 0:
                t1 = (x - knots[i]) / denom1 * B[:, i]
            if i + 1 < n and denom2 > 0:
                t2 = (knots[i + d + 1] - x) / denom2 * B[:, i + 1]
            Bnew[:, i] = t1 + t2
        B = Bnew
    return B[:, :J]


def _make_knots(J, degree=3):
    # nonuniform knots: denser near center
    n_inner = J - degree - 1
    if n_inner < 0:
        n_inner = 0
    # inner knots on [0,1] with cosine spacing (denser near 0.5)
    if n_inner > 0:
        u = np.linspace(0, 1, n_inner + 2)[1:-1]
        inner = 0.5 - 0.5 * np.cos(np.pi * u)  # cosine spacing
    else:
        inner = np.array([])
    knots = np.concatenate([
        np.zeros(degree + 1),
        inner,
        np.ones(degree + 1)
    ])
    return knots


def _spline_to_h(ctrl, knots, J, N):
    """Sample spline at N midpoints of steps on [0,1]."""
    x = (np.arange(N) + 0.5) / N
    B = _bspline_basis(x, knots, J)
    h = B @ ctrl
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return np.ones(N)
    return h / s * N


def _spline_C(logctrl, knots, J, N):
    ctrl = np.exp(np.clip(logctrl, -20, 20))
    h = _spline_to_h(ctrl, knots, J, N)
    return _C(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.95

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            base_h = s.copy()
        else:
            base_h = np.ones(300) / 300
    else:
        base_h = np.ones(300) / 300

    best_h = np.asarray(base_h, dtype=float).copy()
    best_C = _C(best_h)

    # ---- Stage A: global search in spline space ----
    J = 20
    N_spline = 1200
    knots = _make_knots(J, 3)

    # seed control points from base (resized to N_spline, then fit roughly)
    # Use a smooth positive init
    init_ctrl = np.ones(J)
    # try to seed from base by sampling
    try:
        hb = _resize(base_h, N_spline)
        x = (np.arange(N_spline) + 0.5) / N_spline
        B = _bspline_basis(x, knots, J)
        # least squares fit log
        coef, *_ = np.linalg.lstsq(B, hb, rcond=None)
        coef = np.maximum(coef, 1e-6)
        init_ctrl = coef
    except Exception:
        pass

    log_init = np.log(init_ctrl)
    # bounds: log heights in [-8, 8]
    bounds = [(-8.0, 8.0)] * J

    best_logctrl = log_init.copy()
    best_spline_C = _spline_C(log_init, knots, J, N_spline)

    # Differential evolution until 70% budget
    de_deadline = t0 + budget * 0.70
    try:
        from scipy.optimize import differential_evolution
        def obj(lc):
            if time.process_time() > de_deadline:
                raise TimeoutError
            return _spline_C(lc, knots, J, N_spline)
        try:
            res = differential_evolution(
                obj, bounds, popsize=20, maxiter=1000,
                tol=1e-10, mutation=(0.5, 1.0), recombination=0.9,
                polish=False, seed=12345, init='sobol',
                updating='immediate', workers=1
            )
            if res.fun < best_spline_C:
                best_spline_C = res.fun
                best_logctrl = res.x.copy()
        except TimeoutError:
            pass
        except Exception:
            pass
    except Exception:
        pass

    # ---- Stage B: SLSQP refine control points ----
    if time.process_time() - t0 < budget * 0.82:
        try:
            from scipy.optimize import minimize
            def obj(lc):
                return _spline_C(lc, knots, J, N_spline)
            res = minimize(
                obj, best_logctrl, method='SLSQP',
                bounds=bounds,
                options={'maxiter': 300, 'ftol': 1e-14}
            )
            if res.fun < best_spline_C:
                best_spline_C = res.fun
                best_logctrl = res.x.copy()
        except Exception:
            pass

    # ---- Stage C: qnewton at N=1200 from spline candidate ----
    if time.process_time() - t0 < budget * 0.90:
        ctrl = np.exp(np.clip(best_logctrl, -20, 20))
        h1200 = _spline_to_h(ctrl, knots, J, N_spline)
        h1200 = _qnewton_kk(h1200, t0, budget * 0.90, max_iter=200)
        c = _C(h1200)
        if c < best_C:
            best_C = c
            best_h = h1200.copy()

    # ---- Stage D: also try refining base at N=1200 with qnewton ----
    if time.process_time() - t0 < budget * 0.95:
        hb = _resize(base_h, 1200)
        hb = _qnewton_kk(hb, t0, budget * 0.95, max_iter=150)
        c = _C(hb)
        if c < best_C:
            best_C = c
            best_h = hb.copy()

    # ---- Stage E: polish ----
    if time.process_time() - t0 < budget:
        hP = _smooth_polish(best_h, t0, budget)
        c = _C(hP)
        if c < best_C:
            best_C = c
            best_h = hP.copy()

    # always compare with start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if _C(s) < _C(best_h):
                best_h = s.copy()

    best_h = np.asarray(best_h, dtype=float)
    best_h = np.where(np.isfinite(best_h) & (best_h >= 0), best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(300)
    print("final C =", _C(best_h), "N =", len(best_h))
    return best_h

import numpy as np
import time


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _resize(h, N_new):
    N = len(h)
    if N == N_new:
        return np.asarray(h, dtype=float).copy()
    h = np.asarray(h, dtype=float)
    cum = np.concatenate([[0.0], np.cumsum(h)])
    if cum[-1] <= 0:
        return np.ones(N_new)
    cum = cum / cum[-1]
    new_edges = np.arange(N_new + 1) / N_new
    mass = np.interp(new_edges, np.arange(N + 1) / N, cum)
    out = np.diff(mass)
    out = np.maximum(out, 0.0)
    if out.sum() <= 0:
        return np.ones(N_new)
    return out / out.sum() * N_new


def _convolve_fast(h):
    # Use FFT for large N, direct otherwise
    N = len(h)
    if N <= 512:
        return np.convolve(h, h)
    K = 2 * N - 1
    M = 1
    while M < K:
        M *= 2
    fh = np.fft.rfft(h, M)
    return np.fft.irfft(fh * fh, M)[:K]


def _Cfast(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(_convolve_fast(h)) / (s * s)


def _qnewton_kk(h, t0, budget, max_iter=200, tol=1e-14):
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h = h / s
    N = len(h)
    K = 2 * N - 1
    best_h = h.copy()
    best_C = _Cfast(h)
    use_fft = N > 512

    for it in range(max_iter):
        if time.process_time() - t0 > budget:
            break
        support = h > 1e-13
        if not np.any(support):
            break
        idx = np.where(support)[0]
        nS = len(idx)
        if nS < 2:
            break
        conv = _convolve_fast(h) if use_fft else np.convolve(h, h)
        mx = np.max(conv)
        near = np.where(conv >= mx - 1e-10 * mx)[0]
        if len(near) == 0:
            near = np.array([int(np.argmax(conv))])
        g = np.zeros(nS)
        for col, i in enumerate(idx):
            acc = 0.0
            for k in near:
                j = k - i
                if 0 <= j < N:
                    acc += 2.0 * h[j]
            g[col] = acc
        g = g - g.mean()
        near_set = set(near.tolist())
        H = np.zeros((nS, nS))
        for a, i in enumerate(idx):
            for b, j in enumerate(idx):
                ssum = i + j
                if 0 <= ssum < K and ssum in near_set:
                    H[a, b] += 2.0
        P = np.eye(nS) - np.ones((nS, nS)) / nS
        H = P @ H @ P
        try:
            reg = 1e-10 * (np.trace(H) / max(nS, 1) + 1e-14)
            dx = np.linalg.solve(H + reg * np.eye(nS), -g)
        except np.linalg.LinAlgError:
            try:
                dx, *_ = np.linalg.lstsq(H, -g, rcond=None)
            except Exception:
                break
        if not np.all(np.isfinite(dx)):
            break
        best_alpha = 0.0
        best_alpha_C = best_C
        for alpha in [1.0, 0.5, 0.25, 0.1, 0.05, 0.02, 0.01]:
            h_try = h.copy()
            h_try[idx] = h[idx] + alpha * dx
            h_try = np.maximum(h_try, 0.0)
            st = h_try.sum()
            if st <= 0:
                continue
            h_try = h_try / st
            c = _Cfast(h_try)
            if c < best_alpha_C - 1e-16:
                best_alpha_C = c
                best_alpha = alpha
        if best_alpha <= 0:
            break
        h_try = h.copy()
        h_try[idx] = h[idx] + best_alpha * dx
        h_try = np.maximum(h_try, 0.0)
        st = h_try.sum()
        if st <= 0:
            break
        h = h_try / st
        c = _Cfast(h)
        if c < best_C - 1e-16:
            best_C = c
            best_h = h.copy()
        else:
            break
        if np.max(np.abs(dx)) < tol:
            break
    return best_h


def _smooth_polish(h, t0, budget):
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h /= s
    N = len(h)
    best_C = _Cfast(h)
    factors = [0.5, 0.7, 0.85, 0.93, 0.97, 0.99, 1.01, 1.03, 1.07, 1.15, 1.3, 1.5]
    for _ in range(40):
        if time.process_time() - t0 > budget:
            break
        improved = False
        for i in range(N):
            if time.process_time() - t0 > budget:
                break
            base = h[i]
            best_val = base
            for f in factors:
                h[i] = base * f
                c = _Cfast(h)
                if c < best_C - 1e-16:
                    best_C = c
                    best_val = h[i]
                    improved = True
            h[i] = best_val
        ss = h.sum()
        if ss > 0:
            h /= ss
        if not improved:
            break
    return h


def _gradient_descent(h, t0, budget, steps=4000, lr=0.5):
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h = h / s
    N = len(h)
    best_h = h.copy()
    best_C = _Cfast(h)
    step = lr / N
    use_fft = N > 512
    for it in range(steps):
        if time.process_time() - t0 > budget:
            break
        conv = _convolve_fast(h) if use_fft else np.convolve(h, h)
        mx = np.max(conv)
        c = 2.0 * N * mx
        if c < best_C - 1e-15:
            best_C = c
            best_h = h.copy()
        k = int(np.argmax(conv))
        g = np.zeros(N)
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        for i in range(lo, hi + 1):
            j = k - i
            if 0 <= j < N:
                g[i] += 2.0 * h[j]
        g = g - g.mean()
        h = h - step * g
        h = np.maximum(h, 0.0)
        ss = h.sum()
        if ss <= 0:
            break
        h /= ss
    return best_h


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.92

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            base_h = s.copy()
        else:
            base_h = np.ones(300) / 300
    else:
        base_h = np.ones(300) / 300

    best_h = np.asarray(base_h, dtype=float).copy()
    best_C = _Cfast(best_h)
    print("start C =", best_C, "N =", len(best_h))

    # Multi-resolution Newton: try several N, keep best
    resolutions = [len(best_h), 300, 600, 1200, 400]
    for N_try in resolutions:
        if time.process_time() - t0 > budget * 0.75:
            break
        h_try = _resize(best_h, N_try)
        h_try = _qnewton_kk(h_try, t0, budget * 0.75, max_iter=400)
        c = _Cfast(h_try)
        print("  N=", N_try, "C=", c)
        if c < best_C:
            best_C = c
            best_h = h_try.copy()

    # Gradient descent at best resolution
    if time.process_time() - t0 < budget * 0.85:
        hg = _gradient_descent(best_h, t0, budget * 0.85, steps=20000, lr=0.3)
        c = _Cfast(hg)
        if c < best_C:
            best_C = c
            best_h = hg.copy()

    # Newton again on result
    if time.process_time() - t0 < budget * 0.92:
        hK = _qnewton_kk(best_h, t0, budget * 0.92, max_iter=200)
        c = _Cfast(hK)
        if c < best_C:
            best_C = c
            best_h = hK.copy()

    # Smooth polish on smaller resolution to escape local minima
    if time.process_time() - t0 < budget * 0.97:
        hP = _smooth_polish(best_h, t0, budget * 0.97)
        c = _Cfast(hP)
        if c < best_C:
            best_C = c
            best_h = hP.copy()

    # Final Newton polish
    if time.process_time() - t0 < budget:
        hK = _qnewton_kk(best_h, t0, budget, max_iter=100)
        c = _Cfast(hK)
        if c < best_C:
            best_C = c
            best_h = hK.copy()

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if _Cfast(s) < _Cfast(best_h):
                best_h = s.copy()

    best_h = np.asarray(best_h, dtype=float)
    best_h = np.where(np.isfinite(best_h) & (best_h >= 0), best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(300)
    print("final C =", _Cfast(best_h), "N =", len(best_h))
    return best_h

