import numpy as np
import time


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _resize(h, N_new):
    N = len(h)
    if N == N_new:
        return np.asarray(h, dtype=float).copy()
    h = np.asarray(h, dtype=float)
    cum = np.concatenate([[0.0], np.cumsum(h)])
    if cum[-1] <= 0:
        return np.ones(N_new)
    cum = cum / cum[-1]
    new_edges = np.arange(N_new + 1) / N_new
    mass = np.interp(new_edges, np.arange(N + 1) / N, cum)
    out = np.diff(mass)
    out = np.maximum(out, 0.0)
    if out.sum() <= 0:
        return np.ones(N_new)
    return out / out.sum() * N_new


def _polish(h, t0, budget, max_sweeps=40, factors=None):
    if factors is None:
        factors = [0.5, 0.7, 0.85, 0.93, 0.97, 0.99, 1.01, 1.03, 1.07, 1.15, 1.3, 1.5]
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h /= s
    best_C = _C(h)
    N = len(h)
    for _ in range(max_sweeps):
        if time.process_time() - t0 > budget:
            break
        improved = False
        for i in range(N):
            if time.process_time() - t0 > budget:
                break
            base = h[i]
            best_val = base
            for f in factors:
                h[i] = base * f
                c = _C(h)
                if c < best_C - 1e-16:
                    best_C = c
                    best_val = h[i]
                    improved = True
            h[i] = best_val
        ss = h.sum()
        if ss > 0:
            h /= ss
        if not improved:
            break
    return h


def _qnewton_kk(h, t0, budget, max_iter=200, tol=1e-14):
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h = h / s
    N = len(h)
    K = 2 * N - 1
    best_h = h.copy()
    best_C = _C(h)

    for it in range(max_iter):
        if time.process_time() - t0 > budget:
            break
        support = h > 1e-13
        if not np.any(support):
            break
        idx = np.where(support)[0]
        nS = len(idx)
        if nS < 2:
            break
        conv = np.convolve(h, h)
        mx = np.max(conv)
        near = np.where(conv >= mx - 1e-10 * mx)[0]
        if len(near) == 0:
            near = np.array([int(np.argmax(conv))])
        g = np.zeros(nS)
        for col, i in enumerate(idx):
            acc = 0.0
            for k in near:
                j = k - i
                if 0 <= j < N:
                    acc += 2.0 * h[j]
            g[col] = acc
        g = g - g.mean()
        near_set = set(near.tolist())
        H = np.zeros((nS, nS))
        for a, i in enumerate(idx):
            for b, j in enumerate(idx):
                if (i + j) in near_set:
                    H[a, b] += 2.0
        P = np.eye(nS) - np.ones((nS, nS)) / nS
        H = P @ H @ P
        try:
            reg = 1e-10 * (np.trace(H) / max(nS, 1) + 1e-14)
            dx = np.linalg.solve(H + reg * np.eye(nS), -g)
        except np.linalg.LinAlgError:
            try:
                dx, *_ = np.linalg.lstsq(H, -g, rcond=None)
            except Exception:
                break
        if not np.all(np.isfinite(dx)):
            break
        best_alpha = 0.0
        best_alpha_C = best_C
        for alpha in [1.0, 0.5, 0.25, 0.1, 0.05, 0.02, 0.01]:
            h_try = h.copy()
            h_try[idx] = h[idx] + alpha * dx
            h_try = np.maximum(h_try, 0.0)
            st = h_try.sum()
            if st <= 0:
                continue
            h_try = h_try / st
            c = _C(h_try)
            if c < best_alpha_C - 1e-16:
                best_alpha_C = c
                best_alpha = alpha
        if best_alpha <= 0:
            break
        h_try = h.copy()
        h_try[idx] = h[idx] + best_alpha * dx
        h_try = np.maximum(h_try, 0.0)
        st = h_try.sum()
        if st <= 0:
            break
        h = h_try / st
        c = _C(h)
        if c < best_C - 1e-16:
            best_C = c
            best_h = h.copy()
        else:
            break
        if np.max(np.abs(dx)) < tol:
            break
    return best_h


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.92

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            base_h = s.copy()
        else:
            base_h = np.ones(300) / 300.0
    else:
        base_h = np.ones(300) / 300.0

    best_h = np.asarray(base_h, dtype=float).copy()
    best_C = _C(best_h)

    # Iteratively refine at increasing resolution.  Finer grids approximate a
    # continuous optimum better, so we push N up as far as time allows, keeping
    # the best across all resolutions.
    for N in [300, 600, 900, 1200, 1600, 2000]:
        if time.process_time() - t0 > budget * 0.85:
            break
        hN = _resize(best_h, N)
        hN = _qnewton_kk(hN, t0, budget * 0.85, max_iter=300)
        cN = _C(hN)
        if cN < best_C:
            best_C = cN
            best_h = hN.copy()

    # Fine polish at best resolution
    if time.process_time() - t0 < budget:
        hP = _polish(best_h, t0, budget, max_sweeps=30)
        cP = _C(hP)
        if cP < best_C:
            best_C = cP
            best_h = hP.copy()

    # One more Newton at the current resolution
    if time.process_time() - t0 < budget:
        hK = _qnewton_kk(best_h, t0, budget, max_iter=100)
        cK = _C(hK)
        if cK < best_C:
            best_C = cK
            best_h = hK.copy()

    # Final safety polish
    if time.process_time() - t0 < budget:
        hP = _polish(best_h, t0, budget, max_sweeps=15)
        cP = _C(hP)
        if cP < best_C:
            best_C = cP
            best_h = hP.copy()

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if _C(s) < best_C:
                best_h = s.copy()
                best_C = _C(s)

    best_h = np.asarray(best_h, dtype=float)
