def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
    else:
        best = np.ones(50)
    best_c = C_of(best)

    rng = np.random.default_rng(12345)

    # Smooth "triangle-ish" bump as a strong starting family: a raised cosine
    # over a support slightly wider than half, which is known to give C ~ 1.5.
    def raised_cosine(N):
        x = np.linspace(-0.5, 0.5, N)
        return np.maximum(np.cos(np.pi * x), 0.0) ** 1.0

    candidates = []
    for N in (50, 100, 200, 400, 800, 1600, 3200, 6400):
        if time.process_time() > deadline:
            break
        h = raised_cosine(N)
        c = C_of(h)
        candidates.append((c, h))

    for c, h in candidates:
        if c < best_c:
            best_c = c
            best = h

    # Local coordinatewise hill-climb on the current best.
    def refine(h, c, deadline, rounds=200):
        n = len(h)
        step_scale = 0.05
        for r in range(rounds):
            if time.process_time() > deadline:
                break
            improved = False
            idxs = rng.permutation(n)
            for i in idxs:
                if time.process_time() > deadline:
                    break
                old = h[i]
                base = old
                for delta in (base * step_scale, -base * step_scale,
                              base * step_scale * 0.3, -base * step_scale * 0.3):
                    nh = h.copy()
                    nh[i] = max(0.0, old + delta)
                    nc = C_of(nh)
                    if nc < c - 1e-15:
                        h = nh
                        c = nc
                        improved = True
                        break
            if not improved:
                step_scale *= 0.5
                if step_scale < 1e-4:
                    break
        return h, c

    if time.process_time() < deadline:
        best, best_c = refine(best, best_c, deadline)

    return np.asarray(best, dtype=float)

