    H = np.fft.rfft(h, m)
    conv = np.fft.irfft(H * H, m)[: 2 * n - 1]
    return 2.0 * n * float(np.max(conv)) / (s * s)


def _grad_step(h, c, t0, deadline, rng, lr=0.02):
    """Subgradient-style: perturb toward lowering the max convolution knot."""
    n = len(h)
    m = 1
    while m < 2 * n:
        m <<= 1
    H = np.fft.rfft(h, m)
    conv = np.fft.irfft(H * H, m)[: 2 * n - 1]
    k = int(np.argmax(conv))
    # d(conv[k])/dh[i] = h[k-i] + h[k+1-i] (indices into h)
    grad = np.zeros(n)
    for i in range(max(0, k - n + 1), min(n, k + 1)):
        j = k - i
        if 0 <= j < n:
            grad[i] += h[j]
        j = k + 1 - i
        if 0 <= j < n:
            grad[i] += h[j]
    s = h.sum()
    # dC/dh_i ~ (2n/s^2) * grad_i - (2n*max/s^3)*2*s... approximate
