import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    n = len(h)
    m = 1
    while m < 2 * n:
        m <<= 1
    H = np.fft.rfft(h, m)
    conv = np.fft.irfft(H * H, m)[: 2 * n - 1]
    return 2.0 * n * float(np.max(conv)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.2

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
    else:
        N = 800
        x = np.linspace(-1, 1, N)
        base = np.maximum(np.cos(x * np.pi / 2.0) ** 2, 0.0)

    best = base.copy()
    bestC = _C(best)
    rng = np.random.default_rng(2024)

    def upsample(h, N2):
        x_old = np.linspace(0, 1, len(h))
        x_new = np.linspace(0, 1, N2)
        return np.interp(x_new, x_old, h)

    # ---- Step 1: multi-resolution local coordinate descent ----
    # For each N in a ladder, upsample best, then do coordinate moves.
    def coord_descent(h, c, deadline, max_rounds=200):
        N = len(h)
        step = 0.5
        rounds = 0
        while time.process_time() < deadline and rounds < max_rounds:
            rounds += 1
            improved = False
            # cheap full sweep using fft C
            # pick a subset of indices to move (all if N small)
            if N <= 4000:
                idx = np.arange(N)
                rng.shuffle(idx)
            else:
                idx = rng.integers(0, N, size=min(N, 512))
            for i in idx:
                if time.process_time() > deadline:
                    break
                old = h[i]
                if old <= 0:
                    old = 1e-9
                    h[i] = old
                best_fac = 1.0
                best_local = c
                # try multiplicative factors
                for fac in (1.0 + step, 1.0 / (1.0 + step),
                            1.0 + 0.5 * step, 1.0 / (1.0 + 0.5 * step),
                            1.0 - 0.3 * step):
                    if fac <= 0:
                        continue
                    h[i] = old * fac
                    nc = _C_fft(h)
                    if nc < best_local - 1e-15:
                        best_local = nc
                        best_fac = fac
                h[i] = old * best_fac
                if best_fac != 1.0:
                    nc2 = _C(h)
                    if nc2 < c - 1e-15:
                        c = nc2
                        improved = True
                    else:
                        h[i] = old
            if not improved:
                step *= 0.6
                if step < 1e-4:
                    break
        return h, _C(h)

    # Ladder of resolutions
    ladder = [400, 800, 1600, 3200]
    for N2 in ladder:
        if time.process_time() > deadline * 1.0:
            break
        h2 = upsample(best, N2)
        c2 = _C(h2)
        # allocate time proportional to remaining
        rem = deadline - time.process_time()
        sub_deadline = time.process_time() + rem * 0.35
        h2, c2 = coord_descent(h2, c2, sub_deadline)
        if c2 < bestC:
            best, bestC = h2.copy(), c2
        print(f"cd N={N2} C={c2:.9f}")

    # ---- Step 2: smooth parameterization polish at N=3200 ----
    Np = 3200
    h_base = upsample(best, Np)
    c_base = _C(h_base)

    # parameterize via log-heights on a coarse grid + interpolation
    K = 64
    xk = np.linspace(0, 1, K)

    def expand(u):
        c = np.exp(np.clip(u, -20, 20))
        return np.interp(np.linspace(0, 1, Np), xk, c)

    def F(u, beta):
        h = expand(u)
        s = h.sum()
        if s <= 0:
            return 1e10
        conv = np.convolve(h, h)
        m = np.max(conv)
        z = beta * (conv - m)
        lse = m + np.log(np.sum(np.exp(z))) / beta
        return lse - 2.0 * np.log(s) + np.log(2.0 * Np)

    def F_grad(u, beta):
        eps = 1e-5
        g = np.zeros_like(u)
        f0 = F(u, beta)
        for i in range(len(u)):
            up = u.copy()
            up[i] += eps
            g[i] = (F(up, beta) - f0) / eps
        return g

    if time.process_time() < deadline:
        try:
            c0 = np.interp(xk, np.linspace(0, 1, Np), np.maximum(h_base, 1e-6))
            u0 = np.log(np.maximum(c0, 1e-6))
            u = u0.copy()
            for beta in [100, 400, 1600, 6400]:
                if time.process_time() > deadline:
                    break
                res = minimize(F, u, args=(beta,), jac=F_grad,
                               method='L-BFGS-B',
                               options={'maxiter': 120, 'ftol': 1e-12})
                u = res.x
            h_sm = expand(u)
            c_sm = _C(h_sm)
            print(f"smooth C={c_sm:.9f}")
            if c_sm < bestC:
                best, bestC = h_sm.copy(), c_sm
        except Exception:
            pass

    # ---- Step 3: final coordinate descent at N=3200 ----
    if time.process_time() < deadline:
        h3 = upsample(best, 3200)
        c3 = _C(h3)
        h3, c3 = coord_descent(h3, c3, deadline, max_rounds=1000)
        if c3 < bestC:
            best, bestC = h3.copy(), c3
        print(f"final N={len(h3)} C={c3:.9f}")

    return np.asarray(best, dtype=float)

