import time
from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _C_fast(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(fftconvolve(h, h))) / (s * s)


def _spline_sample(ctrl, N):
    # cubic spline through control points uniformly spaced, sampled to N points
    # use numpy interp on a fine grid then smooth via cubic using scipy? keep simple:
    # use scipy CubicSpline
    from scipy.interpolate import CubicSpline
    m = len(ctrl)
    xs = np.linspace(0.0, 1.0, m)
    cs = CubicSpline(xs, ctrl)
    t = np.linspace(0.0, 1.0, N)
    return np.maximum(cs(t), 0.0)


def _block_optimize(h, c, best, bestC, t0, budget, rng):
    N = len(h)
    lengths = [2, 4, 8, 16, 32, 64]
    epsilons = [0.2, 0.1, 0.05, 0.02, 0.01]
    bumps = {}
    for L in lengths:
        if L <= N:
            k = np.arange(L)
            w = 0.5 - 0.5 * np.cos(2.0 * np.pi * (k + 0.5) / L)
            w = w - w.mean()
            bumps[L] = w

    while time.process_time() - t0 < budget:
        L = lengths[rng.integers(0, len(lengths))]
        if L > N:
            continue
        w = bumps[L]
        eps = epsilons[rng.integers(0, len(epsilons))]
        start_idx = int(rng.integers(0, N - L + 1))
        sign = 1.0 if rng.random() < 0.5 else -1.0
        fac = 1.0 + sign * eps * w

        seg = h[start_idx:start_idx + L]
        new_seg = seg * fac
        if np.any(new_seg < 0):
            continue

        old_seg = seg.copy()
        h[start_idx:start_idx + L] = new_seg
        cf = _C_fast(h)
        if cf < c - 1e-14:
            ce = _C(h)
            if ce < c - 1e-15:
                c = ce
                if c < bestC:
                    bestC = c
                    best = h.copy()
            else:
                h[start_idx:start_idx + L] = old_seg
        else:
            h[start_idx:start_idx + L] = old_seg
    return h, c, best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.80

    rng = np.random.default_rng(98765)

    # Phase 1: spline global optimization on N=800
    Np = 800
    m = 12
    ctrl0 = np.linspace(0.5, 1.5, m)

    def obj(ctrl):
        h = _spline_sample(ctrl, Np)
        if h.sum() <= 0:
            return 1e6
        return _C_fast(h)

    # limit spline phase to ~35% of budget
    spline_deadline = t0 + budget * 0.35

    class Stop(Exception):
        pass

    def obj_timed(ctrl):
        if time.process_time() > spline_deadline:
            raise Stop()
        return obj(ctrl)

    best_ctrl = ctrl0
    try:
        res = minimize(obj_timed, ctrl0, method='Nelder-Mead',
                       options={'xatol': 1e-5, 'fatol': 1e-8,
                                'maxiter': 5000, 'maxfev': 20000,
                                'adaptive': True})
        best_ctrl = res.x
    except Stop:
        pass
    except Exception:
        pass

    # Sample best spline to N=3200
    h = _spline_sample(best_ctrl, 3200)
    if h.sum() <= 0:
        h = np.maximum(np.cos(np.linspace(-1, 1, 3200) * np.pi / 2.0) ** 2, 0.0)

    c = _C(h)
    best = h.copy()
    bestC = c

    # Also consider start if it's better
    if start is not None:
        s = np.asarray(start, dtype=float).copy()
        sC = _C(s)
        if sC < bestC:
            best = s.copy()
            bestC = sC
            h = s.copy()
            c = sC

    # Phase 2: block-move optimizer for remaining time
    h, c, best, bestC = _block_optimize(h, c, best, bestC, t0, budget, rng)

    return np.asarray(best, dtype=float)

