        improved = False
        for i in perm:
            if time.process_time() - t0 > budget:
                return h, c
            old = h[i]
            best_local = old
            best_c = c
            for fac in (1.0 + step, 1.0 / (1.0 + step)):
                h[i] = old * fac
                nc = _C_fft(h)
                if nc < best_c - 1e-15:
                    best_c = nc
                    best_local = h[i]
            h[i] = best_local
            if best_local != old:
                c = best_c
                improved = True
        if not improved:
            step *= 0.6
            if step < 1e-5:
                break
        else:
            perm = rng.permutation(N)
    return h, c


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds - 1.2

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
    else:
        N = 400
        x = np.linspace(-1, 1, N)
        best = np.maximum(np.cos(x * np.pi / 2.0) ** 2, 0.0)

    bestC = _C(best)
    rng = np.random.default_rng(987654)

    h = best.copy()
    c = bestC
    N = len(h)
    z = np.log(h + 1e-12)

    def eval_z(zz):
        return _C_fft(np.exp(zz))

    sigma_hi, sigma_lo = 0.1, 0.001
    T_hi, T_lo = 0.01, 1e-5

    it = 0
    max_iters = 4000
    frac = 0.1
    k = max(1, int(N * frac))

    best_z = z.copy()
    bestC_ann = c

    while True:
        elapsed = time.process_time() - t0
        if elapsed > budget * 0.7:
            break
        if it >= max_iters:
            break
        p = it / max_iters
        sigma = sigma_hi * (sigma_lo / sigma_hi) ** p
        T = T_hi * (T_lo / T_hi) ** p

        idx = rng.integers(0, N, size=k)
        znew = z.copy()
        znew[idx] += sigma * rng.standard_normal(k)
        cnew = eval_z(znew)

        if cnew < c:
            z, c = znew, cnew
            if c < bestC_ann:
                bestC_ann = c
                best_z = z.copy()
        else:
            d = cnew - c
            if T > 0 and rng.random() < np.exp(-d / T):
                z, c = znew, cnew

        it += 1

    h = np.exp(best_z)
    c = _C_fft(h)
    if c < bestC:
        best, bestC = h.copy(), c

    # Polish with fast FFT-based coordinate descent
    h2, c2 = _refine(best.copy(), t0, budget, rng)
    if c2 < bestC:
        best, bestC = h2, c2

    # Final exact check
    if _C(best) > bestC + 1e-12:
        best = best  # trust best
    return np.asarray(best, dtype=float)

import numpy as np
import time


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    n = len(h)
    m = 1
    while m < 2 * n:
        m <<= 1
    H = np.fft.rfft(h, m)
    conv = np.fft.irfft(H * H, m)[: 2 * n - 1]
    return 2.0 * n * float(np.max(conv)) / (s * s)


def _conv_fft(h):
    n = len(h)
    m = 1
    while m < 2 * n:
        m <<= 1
    H = np.fft.rfft(h, m)
    return np.fft.irfft(H * H, m)[: 2 * n - 1]


def _C_and_conv(h):
    s = h.sum()
    if s <= 0:
        return np.inf, None
    conv = _conv_fft(h)
    return 2.0 * len(h) * float(np.max(conv)) / (s * s), conv


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
    else:
        N = 800
        x = np.linspace(-1, 1, N)
        base = np.maximum(np.cos(x * np.pi / 2.0) ** 2, 0.0)

    best = base.copy()
    bestC, _ = _C_and_conv(best)
    rng = np.random.default_rng(2024)

    def upsample(h, N2):
        x_old = np.linspace(0, 1, len(h))
        x_new = np.linspace(0, 1, N2)
        return np.interp(x_new, x_old, h)

    def gradient_descent(h, c, deadline, n_iter=200, lr=0.05):
        """Smooth gradient descent on C using all near-max knots (soft-max)."""
        N = len(h)
        for it in range(n_iter):
            if time.process_time() > deadline:
                break
            s = h.sum()
            if s <= 0:
                break
            conv = _conv_fft(h)
            mx = np.max(conv)
            # soft-max weights on knots near max
            thresh = mx * (1.0 - 1e-3)
            mask = conv >= thresh
            w = np.where(mask, np.exp((conv - mx) * 1e4), 0.0)
            w /= w.sum()
            # gradient of weighted conv at knots
            grad = np.zeros(N)
            idx = np.where(mask)[0]
            for k in idx:
                wk = w[k]
                if wk < 1e-12:
                    continue
                i_lo = max(0, k - N + 1)
                i_hi = min(N - 1, k)
                for i in range(i_lo, i_hi + 1):
                    j = k - i
                    if 0 <= j < N:
                        grad[i] += wk * h[j]
                    j = k + 1 - i
                    if 0 <= j < N:
                        grad[i] += wk * h[j]
            # dC/dh = 2N/s^2 * grad - 2C/s
            g = (2.0 * N / (s * s)) * grad - (2.0 * c / s)
            gn = np.max(np.abs(g))
            if gn < 1e-15:
                break
            h_new = h - lr * g / gn * s * 0.01
            h_new = np.maximum(h_new, 0.0)
            if h_new.sum() <= 0:
                break
            cn, _ = _C_and_conv(h_new)
            if cn < c - 1e-15:
                h, c = h_new, cn
            else:
                lr *= 0.7
                if lr < 1e-6:
                    break
        return h, c

    def refine(h, c, deadline, step0=0.4):
        N = len(h)
        step = step0
        while time.process_time() < deadline:
            improved = False
            idx = rng.integers(0, N, size=min(N, 128))
            for i in idx:
                if time.process_time() > deadline:
                    break
                old = h[i]
                for fac in (1.0 + step, 1.0 / (1.0 + step), 1.0 - step * 0.5):
                    if fac <= 0:
                        continue
                    h[i] = old * fac
                    nc = _C_fft(h)
                    if nc < c - 1e-15:
                        nc2, _ = _C_and_conv(h)
                        if nc2 < c - 1e-15:
                            c = nc2
                            old = h[i]
                            improved = True
                            continue
                    h[i] = old
            if not improved:
                step *= 0.7
                if step < 1e-5:
                    break
        return h, c

    # Stage 1: upsample to 12800 and refine
    N1 = 12800
    h = upsample(best, N1)
    c, _ = _C_and_conv(h)
    if c < bestC:
        best, bestC = h.copy(), c
    h, c = refine(h, c, t0 + budget_seconds * 0.30)
    if c < bestC:
        best, bestC = h.copy(), c
    print(f"stage1 N={len(h)} C={c:.9f}")

    # Stage 2: upsample to 25600 and refine
    if time.process_time() - t0 < budget_seconds * 0.45:
        N2 = 25600
        h2 = upsample(best, N2)
        c2, _ = _C_and_conv(h2)
        if c2 < bestC:
            best, bestC = h2.copy(), c2
        h2, c2 = refine(h2, c2, t0 + budget_seconds * 0.60)
        if c2 < bestC:
            best, bestC = h2.copy(), c2
        print(f"stage2 N={len(h2)} C={c2:.9f}")
    else:
        h2, c2 = h, c

    # Stage 3: gradient descent on smooth soft-max
    if time.process_time() - t0 < budget_seconds * 0.65:
        h2, c2 = gradient_descent(h2, c2, t0 + budget_seconds * 0.85, n_iter=300, lr=0.1)
        if c2 < bestC:
            best, bestC = h2.copy(), c2
        print(f"stage3 N={len(h2)} C={c2:.9f}")

    # Stage 4: final coordinate refine
    if time.process_time() - t0 < budget_seconds * 0.90:
        h2, c2 = refine(h2, c2, deadline, step0=0.1)
        if c2 < bestC:
            best, bestC = h2.copy(), c2
        print(f"stage4 N={len(h2)} C={c2:.9f}")

    return np.asarray(best, dtype=float)

import numpy as np
import time


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _conv(h):
    n = len(h)
    m = 1
    while m < 2 * n:
        m <<= 1
    H = np.fft.rfft(h, m)
    return np.fft.irfft(H * H, m)[:2 * n - 1]


def _C_fft_conv(conv, n, s):
    return 2.0 * n * float(np.max(conv)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.2

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.maximum(base, 0.0)
    else:
        N = 800
        x = np.linspace(-1, 1, N)
        base = np.maximum(np.cos(x * np.pi / 2.0) ** 2, 0.0)

    s = base.sum()
    if s > 0:
        base /= s
    best = base.copy()
    bestC = _C(best)
    rng = np.random.default_rng(777)

    def upsample(h, N2):
        x_old = np.linspace(0, 1, len(h))
        x_new = np.linspace(0, 1, N2)
        return np.interp(x_new, x_old, h)

    # Coordinate descent using incremental FFT-based convolution with caching.
    def coord_descent(h, c, dl, max_rounds=500):
        N = len(h)
        step = 0.3
        rounds = 0
        while time.process_time() < dl and rounds < max_rounds:
            rounds += 1
            improved = False
            idx = np.arange(N)
            rng.shuffle(idx)
            for i in idx:
                if time.process_time() > dl:
                    break
                old = h[i]
                if old <= 1e-12:
                    old = 1e-9
                    h[i] = old
                s = h.sum()
                best_fac = 1.0
                best_local = c
                for fac in (1.0 + step, 1.0 / (1.0 + step),
                            1.0 + 0.5 * step, 1.0 / (1.0 + 0.5 * step),
                            1.0 - 0.4 * step):
                    if fac <= 0:
                        continue
                    h[i] = old * fac
                    s2 = s - old + h[i]
                    conv = _conv(h)
                    nc = _C_fft_conv(conv, N, s2)
                    if nc < best_local - 1e-14:
                        best_local = nc
                        best_fac = fac
                h[i] = old * best_fac
                if best_fac != 1.0:
                    s2 = s - old + h[i]
                    ce = _C(h)
                    if ce < c - 1e-14:
                        c = ce
                        improved = True
                    else:
                        h[i] = old
            if not improved:
                step *= 0.6
                if step < 1e-5:
                    break
        return h, _C(h)

    # Step 1: coordinate descent on input (same N as start)
    h = best.copy()
    c = bestC
    h, c = coord_descent(h, c, t0 + (deadline - t0) * 0.45)
    if c < bestC:
        best, bestC = h.copy(), c
    print(f"cd1 N={len(best)} C={bestC:.9f}")

    # Step 2: upsample to higher N and refine
    for Np in (6400, 9600):
        if time.process_time() > deadline:
            break
        h_up = upsample(best, Np)
        s_up = h_up.sum()
        if s_up > 0:
            h_up /= s_up
        c_up = _C(h_up)
        rem = deadline - time.process_time()
        sub_dl = time.process_time() + rem * 0.85
        h_up, c_up = coord_descent(h_up, c_up, sub_dl, max_rounds=300)
        if c_up < bestC:
            best, bestC = h_up.copy(), c_up
        print(f"cd N={Np} C={c_up:.9f}")

    return np.asarray(best, dtype=float)
